package com.spaceagent.platform.runtime;import com.spaceagent.platform.runtime.domain.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;
class SupervisorPolicyResolutionTest {static final String H="sha256:"+"a".repeat(64);@Test void runningPolicyStaysPinnedAndUnknownDoesNotFallback(){var pinned=new SupervisorPolicy(SupervisorPolicyMode.OPT_IN,false,true,H,Instant.EPOCH);assertThat(SupervisorPolicyResolution.forRunningRun(pinned,false).policy()).isSameAs(pinned);var unknown=SupervisorPolicyResolution.forRunningRun(pinned,true);assertThat(unknown.outcome()).isEqualTo(SupervisorPolicyResolution.Outcome.UNKNOWN_BLOCKED);assertThat(unknown.policy()).isSameAs(pinned);}@Test void killSwitchForcesOnlyNewRunsToDeterministic(){var requested=new SupervisorPolicy(SupervisorPolicyMode.SELECTED_DEFAULT,false,true,H,Instant.EPOCH);var resolved=SupervisorPolicyResolution.forNewRun(requested,true,false);assertThat(resolved.outcome()).isEqualTo(SupervisorPolicyResolution.Outcome.FORCED_DETERMINISTIC);assertThat(resolved.policy().mode()).isEqualTo(SupervisorPolicyMode.DETERMINISTIC);assertThat(SupervisorPolicyResolution.forNewRun(requested,false,true).outcome()).isEqualTo(SupervisorPolicyResolution.Outcome.UNKNOWN_BLOCKED);}}
